const CACHE='haru-clock-web-17';const FILES=["./", "./index.html", "./style.css?v=12", "./app.js?v=17", "./core.js?v=10", "./i18n.js?v=12", "./fonts.js?v=6", "./manifest.webmanifest", "./icon.svg", "./fonts/BarlowCondensed-OFL.txt", "./fonts/BarlowCondensed.ttf", "./fonts/Orbitron-OFL.txt", "./fonts/Orbitron.ttf", "./fonts/Quicksand-OFL.txt", "./fonts/Quicksand.ttf", "./fonts/Rajdhani-OFL.txt", "./fonts/Rajdhani.ttf", "./fonts/ShareTechMono-OFL.txt", "./fonts/ShareTechMono.ttf", "./fonts/Teko-OFL.txt", "./fonts/Teko.ttf"];self.addEventListener('install',e=>e.waitUntil(caches.open(CACHE).then(c=>c.addAll(FILES)).then(()=>self.skipWaiting())));self.addEventListener('activate',e=>e.waitUntil(caches.keys().then(keys=>Promise.all(keys.filter(k=>k.startsWith('haru-clock-')&&k!==CACHE).map(k=>caches.delete(k)))).then(()=>self.clients.claim())));self.addEventListener('fetch',e=>{if(e.request.method!=='GET'||new URL(e.request.url).origin!==self.location.origin)return;if(e.request.mode==='navigate'){e.respondWith(fetch(e.request).catch(()=>caches.match('./index.html')));return;}e.respondWith(caches.match(e.request).then(c=>c||fetch(e.request)))});
